"""Freeze complete original TEST membership and existing model bytes, no ML."""
import pathlib,argparse,datetime,subprocess,shutil
from common import read,sha,write,setup
def main():
 ap=argparse.ArgumentParser();ap.add_argument('--stage',required=True);a=ap.parse_args();s=pathlib.Path(a.stage).resolve();assert s.parent.name=='runs'
 rt=s.parent.parent;parent=rt/'runs/portal_decoder_20261113_attempt2';cohort=rt/'runs/final_staged_20261112_attempt1/registration/protocol.json';meta=read(cohort);q=read(parent/'main_protocol.json');r=read(parent/'main/result.json');assert r['status']=='completed' and all(r['owner_mean_criterion'].values());assert read(parent/'saved_audit.json')['status']=='passed'
 manifest=read(s/'source_manifest.json');assert sha(cohort)=='2716a20b1b8c251466e35f7e93b750a3ab72b668c38d0199f9026b9c884f675f'
 models=read(parent/'main/sealed_before_victim.json')['models'];base=read(rt/'runs/local_swap_20261113_attempt1/registration/protocol.json')
 assert sha(rt/'runs/local_swap_20261113_attempt1/registration/protocol.json')=='4efd6f81f7c466917b25f4af0fbfb8ca1a2fd204904353c4ea0cb4215f143bda'
 groups=meta['test_groups'];members=meta['test_members'];assert len(groups)==len(set(groups))==909 and sum(len(members[str(g)]) for g in groups)==10515
 assert len({n for g in groups for n in members[str(g)]})==1221
 assert not {n for ns in base['train_members'].values() for n in ns}&{n for ns in members.values() for n in ns}
 assert shutil.disk_usage(s).free>=32*1024**3
 p=dict(schema='portal_complete_cohort_v1',status='frozen',owner_authorization='Prior explicit conditional instruction to run full experiment when development exceeds native and random; both candidates pass.',TEST_allowed=True,frozen_utc=datetime.datetime.now(datetime.timezone.utc).isoformat(),source_commit=manifest['source_commit'],sources=manifest['files'],runtime_root=str(rt),runtime_commit='ca093d8b12ea153a076b02bbdbc4ede58508560c',parent=str(parent),parent_protocol_sha256=sha(parent/'main_protocol.json'),cohort_protocol=str(cohort),cohort_protocol_sha256=sha(cohort),teacher_sha256=q['teacher_sha256'],models=models,author_base=base,seeds=[0,1,2],arms=['native','neural','random_neural','direct','random_direct'],test_groups=groups,test_members=members,preflight_groups=q['train_groups'][:2],resources=dict(main_seconds=43200,CPU_threads=4,nice=10,GPU_hours=0,API_calls=0,automatic_retry=False),caps=dict(main_generations=2727,physical_canonical_builds=24543,own_teacher_batched_forwards=2727,own_teacher_hard_contexts=24543,policy_forwards=2727,official_GAGA_TEST=13635,updates=0),criterion='Each candidate pooled wrong count exceeds native and its own matched random; report both/all repeats/nominal t95. No all-repeat-positive requirement.',scope=['Full original TEST cohort; historical TEST from other studies already observed, not untouched confirmation.','Existing downstream models reused without retraining/selection. One author checkpoint,three generation-noise repetitions.','Original TRAIN-only benign bank and independent teacher unchanged. Same graph budget,broader context access and additional surrogate information/compute.','All physical canonical options/choices sealed before original GAGA load; final scoring uses those actual graph inputs.','No outcome peeking/tuning/filtering/replacement or cap expansion; preserve failures and all denominators.'])
 write(s/'protocol.json',p);setup(s);print(dict(status='frozen',protocol_sha256=sha(s/'protocol.json'),model_calls=0,checkpoint_loads=0,TEST_prediction_reads=0),flush=True)
if __name__=='__main__':main()
